import './style.css';
import {catalog,catalogMap,categories} from './catalog';
import {applyFinish,panelFinishes} from './finishes';
import {clone,emptyProject,PANEL_H,panelWidth,parseProject,uid,type Item,type Project} from './model';
import {bounds,componentSvg,cutoutSvg,esc,mountingSvg,panelFinishDefs,panelFinishSurface} from './svg';

const PX=4, grids=[.5,1,2.54,5.08];
let project=load(), selection=new Set<string>(), history:Project[]=[clone(load())], historyIndex=0;
const openingZoom=Math.min(1.9,Math.max(1.18,(window.innerHeight-180)/(PANEL_H*PX)));
let gridIndex=1,snap=true,smartGuides=true,zoom=openingZoom,view:'design'|'cutout'|'rear'='design',showSafe=true,showGrid=true,libraryQuery='',activeCategory='All',inspectorTab:'context'|'panel'|'layers'='context',leftOpen=true,rightOpen=true;
let drag:null|{startX:number;startY:number;orig:Map<string,{x:number;y:number}>;moved:boolean}=null;
let toastTimer=0;

const icon=(name:'undo'|'redo'|'folder'|'save'|'plus'|'export'|'trash'|'left'|'right'|'help')=>{const paths={undo:'M9 7H4V2M4 7l4-4M4 7a7 7 0 1 0 2-5',redo:'M15 7h5V2m0 5-4-4m4 4a7 7 0 1 1-2-5',folder:'M3 6h7l2 2h9v11H3z',save:'M5 3h12l2 2v16H5zM8 3v6h8V3M8 15h8v6H8z',plus:'M12 5v14M5 12h14',export:'M12 16V3m-5 5 5-5 5 5M5 14v7h14v-7',trash:'M4 7h16M9 7V4h6v3m-8 0 1 14h8l1-14',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',help:'M9.5 9a2.5 2.5 0 1 1 3 2.45c-.5.2-.5.8-.5 1.55M12 18h.01'};return`<svg class="ui-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]}"/></svg>`;};

const app=document.querySelector<HTMLDivElement>('#app')!;
app.innerHTML=`<main class="app">
 <header class="topbar"><a class="brand" href="/" aria-label="Five08 home"><div class="brand-mark"></div><div><strong>five08</strong><small>Eurorack panel designer</small></div></a><span class="top-divider"></span><div class="project-identity"><span class="eyebrow">Project</span><input class="project-name" id="project-name" aria-label="Project name"></div><div class="history-group"><button class="icon-button" id="undo" aria-label="Undo" data-tooltip="Undo · ⌘Z">${icon('undo')}</button><button class="icon-button" id="redo" aria-label="Redo" data-tooltip="Redo · ⇧⌘Z">${icon('redo')}</button></div><span class="spacer"></span><div class="file-group"><button class="tool-button subtle" id="new-project">${icon('plus')}<span>New</span></button><button class="tool-button subtle" id="open-json">${icon('folder')}<span>Open</span></button><button class="tool-button subtle" id="save-json">${icon('save')}<span>Save</span></button></div><button class="tool-button primary export-button" id="export">${icon('export')} Export</button><button class="icon-button" id="help" aria-label="Keyboard shortcuts" data-tooltip="Help & shortcuts">${icon('help')}</button><input id="file-input" type="file" accept=".json,application/json" hidden></header>
 <div class="layout"><aside class="sidebar library"><div class="side-head"><div><span class="eyebrow">Create</span><h2>Components</h2></div><div class="head-actions"><span id="library-count"></span><button class="collapse-button" id="collapse-left" aria-label="Collapse component library">${icon('left')}</button></div></div><div class="library-tools"><div class="search-wrap"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6"/><path d="m16 16 4 4"/></svg><input id="library-search" type="search" placeholder="Search parts, families, makers…" aria-label="Search components"></div><div class="category-tabs" id="category-tabs"></div></div><div class="side-scroll" id="library"></div></aside>
 <section class="canvas-wrap"><div class="precision-bar"><button class="collapse-rail left-rail" id="open-left" aria-label="Show component library">${icon('right')}</button><div class="segmented" id="views" role="group" aria-label="Panel view"><button data-view="design">Hardware</button><button data-view="cutout">Cutouts</button><button data-view="rear">Rear clearance</button></div><div class="mode-context" id="mode-context"><span></span><small></small></div><span class="spacer"></span><div class="layout-tools" role="toolbar" aria-label="Alignment"><button class="quiet" id="align-x" data-tooltip="Align horizontal centres">Align X</button><button class="quiet" id="align-y" data-tooltip="Align vertical centres">Align Y</button><button class="quiet" id="distribute-h" data-tooltip="Equal horizontal spacing">Space H</button><button class="quiet" id="distribute-v" data-tooltip="Equal vertical spacing">Space V</button><button class="quiet" id="center-panel" data-tooltip="Centre selection on panel">Centre</button></div><span class="precision-divider"></span><button class="quiet on" id="smart-guides">Smart guides</button><button class="quiet" id="toggle-safe">Safe zones</button><button class="collapse-rail right-rail" id="open-right" aria-label="Show inspector">${icon('left')}</button></div><div class="ruler-corner">0,0</div><div class="ruler ruler-x" id="ruler-x"></div><div class="ruler ruler-y" id="ruler-y"></div><div class="canvas" id="canvas"><div class="panel-stage" id="panel-stage"></div></div><div class="selection-bar" id="selection-bar"></div><div class="canvas-toolbar"><div class="toolbar-group"><button id="zoom-out" aria-label="Zoom out">−</button><button id="zoom-fit">Fit panel</button><button id="zoom-100">100%</button><button id="zoom-in" aria-label="Zoom in">+</button></div><span></span><div class="toolbar-group"><button id="snap-toggle">Grid snap</button><button id="grid-cycle">1 mm</button><button id="grid-toggle">Grid</button></div></div></section>
 <aside class="sidebar right"><div class="side-head"><div><span class="eyebrow">Inspect</span><h2 id="inspector-title">Panel</h2></div><div class="head-actions"><button class="icon-button danger" id="delete" aria-label="Delete selection" data-tooltip="Delete selection">${icon('trash')}</button><button class="collapse-button" id="collapse-right" aria-label="Collapse inspector">${icon('right')}</button></div></div><nav class="inspector-tabs" aria-label="Inspector sections"><button data-inspector-tab="context">Context</button><button data-inspector-tab="panel">Panel</button><button data-inspector-tab="layers">Layers <span id="layers-count"></span></button></nav><div class="side-scroll" id="inspector"></div></aside></div>
 <footer class="statusbar"><button class="status-control ready" id="save-status">● Saved locally</button><span id="dimensions"></span><span id="selection-status"></span><span id="coordinates">X — · Y —</span><span class="spacer"></span><span id="zoom-status">100%</span><span id="snap-status">Snap · 1 mm</span><button class="status-control" id="warning-count"></button></footer>
</main><div class="toast" id="toast" role="status" aria-live="polite"></div>`;

function load():Project{try{const raw=localStorage.getItem('five08-project-v2')||localStorage.getItem('panel-studio-project-v2')||localStorage.getItem('panel-studio-project');return raw?parseProject(JSON.parse(raw),catalogMap):emptyProject();}catch{return emptyProject();}}
function persist(){const s=document.querySelector('#save-status')!;s.textContent='● SAVING';try{localStorage.setItem('five08-project-v2',JSON.stringify(project));setTimeout(()=>s.textContent='● SAVED JUST NOW',180);}catch{s.textContent='● SAVE FAILED';}}
function saveRecovery(){try{const raw=localStorage.getItem('five08-recovery'),items=raw?JSON.parse(raw):[];localStorage.setItem('five08-recovery',JSON.stringify([{savedAt:new Date().toISOString(),project:clone(project)},...(Array.isArray(items)?items:[])].slice(0,5)));}catch{/* best effort */}}
function mutate(fn:()=>void){fn();history=history.slice(0,historyIndex+1);history.push(clone(project));if(history.length>100)history.shift();historyIndex=history.length-1;persist();render();}
function notify(s:string){const e=document.querySelector('#toast')!;window.clearTimeout(toastTimer);e.textContent=s;e.classList.add('show');toastTimer=window.setTimeout(()=>e.classList.remove('show'),2200);}
function sv(v:number){return snap?Math.round(v/grids[gridIndex])*grids[gridIndex]:Math.round(v*10)/10;}
function selectedItems(){return project.items.filter(i=>selection.has(i.id));}

function render(){renderLibrary();renderCanvas();renderInspector();renderChrome();}
function renderChrome(){(document.querySelector('#project-name') as HTMLInputElement).value=project.name;const w=panelWidth(project.panel),items=selectedItems();document.querySelector('#dimensions')!.textContent=`${project.panel.hp} HP · ${w.toFixed(2)} × ${PANEL_H} mm`;document.querySelector('#selection-status')!.textContent=items.length===1?`${catalogMap.get(items[0].componentId)!.name} · X ${items[0].x.toFixed(1)} Y ${items[0].y.toFixed(1)}`:items.length>1?`${items.length} selected`:`${project.items.length} components`;document.querySelector('#zoom-status')!.textContent=`${Math.round(zoom*100)}%`;document.querySelector('#snap-status')!.textContent=`${smartGuides?'Guides':'No guides'} · ${snap?`${grids[gridIndex]} mm grid`:'free'}`;const warnings=preflight();const wc=document.querySelector('#warning-count')!;wc.textContent=warnings.length?`▲ ${warnings.length} issue${warnings.length===1?'':'s'}`:'✓ No layout conflicts';wc.classList.toggle('warn',warnings.length>0);(document.querySelector('#undo') as HTMLButtonElement).disabled=historyIndex===0;(document.querySelector('#redo') as HTMLButtonElement).disabled=historyIndex===history.length-1;(document.querySelector('#delete') as HTMLButtonElement).disabled=selection.size===0;(document.querySelector('#align-x') as HTMLButtonElement).disabled=selection.size<2;(document.querySelector('#align-y') as HTMLButtonElement).disabled=selection.size<2;(document.querySelector('#distribute-h') as HTMLButtonElement).disabled=selection.size<3;(document.querySelector('#distribute-v') as HTMLButtonElement).disabled=selection.size<3;(document.querySelector('#center-panel') as HTMLButtonElement).disabled=selection.size===0;document.querySelector('#snap-toggle')!.classList.toggle('on',snap);document.querySelector('#smart-guides')!.classList.toggle('on',smartGuides);document.querySelector('#grid-toggle')!.classList.toggle('on',showGrid);document.querySelector('#toggle-safe')!.classList.toggle('on',showSafe);document.querySelectorAll('[data-view]').forEach(e=>{const on=(e as HTMLElement).dataset.view===view;e.classList.toggle('on',on);e.setAttribute('aria-pressed',String(on));});document.querySelectorAll('[data-inspector-tab]').forEach(e=>{const on=(e as HTMLElement).dataset.inspectorTab===inspectorTab;e.classList.toggle('on',on);e.setAttribute('aria-selected',String(on));});document.querySelector('.layout')!.classList.toggle('left-closed',!leftOpen);document.querySelector('.layout')!.classList.toggle('right-closed',!rightOpen);document.querySelector('#layers-count')!.textContent=String(project.items.length);const context={design:['Hardware view','Front-panel controls and artwork'],cutout:['Machining view','Cutouts and drilling geometry'],rear:['Rear clearance','Bodies, depth and keepout zones']}[view];document.querySelector('#mode-context')!.innerHTML=`<span>${context[0]}</span><small>${context[1]}</small>`;renderSelectionBar();}

function renderLibrary(){const tabs=document.querySelector('#category-tabs')!;tabs.innerHTML=['All',...categories].map(c=>`<button class="category-pill ${c===activeCategory?'on':''}" data-category="${c}">${c==='All'?'All parts':c}</button>`).join('');tabs.querySelectorAll<HTMLElement>('[data-category]').forEach(b=>b.onclick=()=>{activeCategory=b.dataset.category!;renderLibrary();});const q=libraryQuery.trim().toLowerCase();const defs=catalog.filter(d=>(activeCategory==='All'||d.category===activeCategory)&&(!q||[d.name,d.description,...d.tags,d.manufacturer||''].some(x=>x.toLowerCase().includes(q))));document.querySelector('#library-count')!.textContent=`${defs.length} parts`;const groups=activeCategory==='All'?[...categories]:[activeCategory];document.querySelector('#library')!.innerHTML=groups.map(cat=>{const ds=defs.filter(d=>d.category===cat);return ds.length?`<section class="library-section"><div class="section-label">${cat}<span>${ds.length}</span></div><div class="component-list">${ds.map(d=>`<button class="component-row" data-component="${d.id}" draggable="true" aria-label="Add ${d.name}"><span class="part-thumbnail">${partThumbnail(d.renderer,d.color,d.orientation,d.id)}</span><span class="part-copy"><strong>${d.name}</strong><small><b>${d.width} × ${d.height}</b>${d.cutout?` · ${cutoutText(d)}`:''}${d.status==='verified'?' · Verified':''}</small></span><span class="add-part" aria-hidden="true">Add</span></button>`).join('')}</div></section>`:''}).join('')||`<div class="empty-library"><strong>No matching parts</strong><span>Try another name, family or manufacturer.</span></div>`;document.querySelectorAll<HTMLElement>('[data-component]').forEach(b=>{b.onclick=()=>add(b.dataset.component!);b.ondragstart=e=>e.dataTransfer?.setData('component',b.dataset.component!);});}
function partIcon(r:string){return({knob:'◉',jack:'○',slider:'↕',button:'●',toggle:'╱',led:'✦',display:'▣',connector:'⌑',hole:'⊗',text:'T',shape:'◇',touch:'◫',image:'▧'} as Record<string,string>)[r]||'·';}
function cutoutText(d:(typeof catalog)[number]){const rect=d.renderer==='button'&&(d.id.includes('square')||d.id.includes('rect')||d.id.includes('wide'));return rect?`${(d.width*.8).toFixed(1)} × ${(d.height*.8).toFixed(1)} cutout`:`Ø${d.cutout} cutout`;}
function finishStyle(id:string){return({
 'brushed-silver':'linear-gradient(100deg,#aeb1ae,#ecece7 25%,#b8bbb7 55%,#f3f3ee 78%,#a8aaa7)',
 'black-anodized':'linear-gradient(135deg,#292d2a,#0f1210 55%,#252925)',
 'powder-white':'radial-gradient(circle at 30% 20%,#fff,#e4e2da 75%,#cccac3)',
 'smoke-acrylic':'linear-gradient(135deg,#60706cdd,#1b2421f2 50%,#35433fee)',
 'clear-acrylic':'linear-gradient(135deg,#f3ffffee,#b7d0ccbb 48%,#ffffffee 55%,#9ebbb7cc)',
 'fr4-green':'radial-gradient(circle at 20% 30%,#35745b,#0b3527 65%,#08271e)',
 'brushed-copper':'linear-gradient(100deg,#74422f,#d18a61 28%,#945039 56%,#d99569 78%,#6c3b2b)',
 'walnut':'radial-gradient(circle at 35% 20%,#dedfd9,#bfc0ba 58%,#a7a9a3)'} as Record<string,string>)[id]||'#ccc';}
function finishCards(){return panelFinishes.map(f=>`<button class="finish-card ${project.panel.finish===f.id?'selected':''}" data-finish="${f.id}" aria-label="Use ${f.name}"><span class="finish-swatch" style="background:${finishStyle(f.id)}"></span><span><strong>${f.name}</strong><small>${f.material}</small></span>${project.panel.finish===f.id?'<b>✓</b>':''}</button>`).join('');}
function imageControl(i:Item){return`<div class="image-object-control ${i.imageData?'has-image':''}">${i.imageData?`<span class="surface-preview" style="background-image:url('${i.imageData}')"></span><span><strong>PNG loaded</strong><small>Transparency is preserved</small></span><button class="surface-remove" id="remove-item-image" type="button">Remove</button>`:`<span class="surface-upload-icon">＋</span><span><strong>Add a PNG</strong><small>Transparent artwork, logo or texture</small></span><label class="surface-upload">Choose<input id="item-image-file" type="file" accept="image/png" hidden></label>`}</div><p class="surface-note">PNG only · maximum 1.5 MB · resize with Width and Height</p>`;}
function partThumbnail(r:string,color:string,orientation?:string,id=''){const common=`stroke="#343831" stroke-width="1.5"`;let s='';if(r==='knob'){const enc=id.includes('encoder'),ring=id==='encoder-ring';s=`${ring?`<circle cx="18" cy="18" r="13" fill="none" stroke="#a9ff70" stroke-width="2" stroke-dasharray="3 2"/>`:''}<circle cx="18" cy="18" r="10" fill="${color}" ${common}/>${enc?`<circle cx="18" cy="18" r="4" fill="none" stroke="#737a71"/><circle cx="18" cy="11" r="1" fill="#c8ff5a"/>`:`<path d="M18 18l4-7" stroke="#ff7659" stroke-width="2"/>`}`;}else if(r==='jack')s=`<circle cx="18" cy="18" r="10" fill="#d8d6cd" ${common}/><circle cx="18" cy="18" r="5" fill="#171916"/>`;else if(r==='slider')s=orientation==='horizontal'?`<path d="M6 18h24" ${common}/><rect x="15" y="13" width="6" height="10" rx="2" fill="#ddd"/>`:`<path d="M18 5v26" ${common}/><rect x="12" y="14" width="12" height="7" rx="2" fill="#ddd"/>`;else if(r==='led')s=`<circle cx="18" cy="18" r="5" fill="${color}"/><circle cx="18" cy="18" r="9" fill="none" stroke="${color}" opacity=".2" stroke-width="3"/>`;else if(r==='display')s=`<rect x="5" y="10" width="26" height="16" rx="2" fill="#08100c" ${common}/><path d="M9 19l5-4 5 6 8-7" fill="none" stroke="${color}"/>`;else if(r==='button'){const rect=id.includes('square')||id.includes('rect')||id.includes('wide'),lit=id.includes('lit');s=rect?`<rect x="${id.includes('wide')?3:8}" y="${id.includes('wide')?11:8}" width="${id.includes('wide')?30:20}" height="${id.includes('wide')?14:20}" rx="3" fill="${color}" ${common}/>${lit?`<rect x="${id.includes('wide')?7:11}" y="${id.includes('wide')?14:11}" width="${id.includes('wide')?22:14}" height="${id.includes('wide')?8:14}" rx="2" fill="#fff" opacity=".32"/>`:''}`:`<circle cx="18" cy="18" r="${id.includes('arcade')?13:9}" fill="${color}" ${common}/>`;}else if(r==='toggle')s=`<circle cx="18" cy="21" r="6" fill="#ccc" ${common}/><path d="M18 18l5-10" stroke="#ddd" stroke-width="3" stroke-linecap="round"/>`;else s=`<rect x="8" y="8" width="20" height="20" rx="4" fill="none" ${common}/><text x="18" y="22" text-anchor="middle" fill="#9da294" font-size="10">${partIcon(r)}</text>`;return`<svg viewBox="0 0 36 36" aria-hidden="true">${s}</svg>`;}

function renderCanvas(){const w=panelWidth(project.panel),stage=document.querySelector<HTMLDivElement>('#panel-stage')!;stage.style.width=`${w*PX*zoom}px`;stage.style.height=`${PANEL_H*PX*zoom}px`;const safe=showSafe?`<g class="design-guide"><rect x="3" y="3" width="${w-6}" height="${PANEL_H-6}" rx="1" fill="none" stroke="${project.accentColor}" stroke-opacity=".35" stroke-width=".3" stroke-dasharray="1 1"/><rect width="${w}" height="8" fill="${project.accentColor}" opacity=".045"/><rect y="${PANEL_H-8}" width="${w}" height="8" fill="${project.accentColor}" opacity=".045"/></g>`:'';const grid=showGrid?`<rect class="design-guide" width="${w}" height="${PANEL_H}" fill="url(#grid)"/>`:'';const visible=project.items.filter(i=>!i.hidden);stage.innerHTML=`<svg class="panel-svg" id="panel-svg" width="${w*PX}" height="${PANEL_H*PX}" viewBox="0 0 ${w} ${PANEL_H}" style="transform:scale(${zoom});transform-origin:top left"><defs>${panelFinishDefs(project)}<pattern id="grid" width="${grids[gridIndex]}" height="${grids[gridIndex]}" patternUnits="userSpaceOnUse"><path d="M ${grids[gridIndex]} 0H0V${grids[gridIndex]}" fill="none" stroke="${project.inkColor}" stroke-opacity=".08" stroke-width=".1"/></pattern><filter id="glow"><feGaussianBlur stdDeviation="1" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter><style>.cut{fill:none;stroke:#ef523c;stroke-width:.45}.panel-item:focus{outline:none}.smart-line{stroke:#168cff;stroke-width:.42;vector-effect:non-scaling-stroke}.measure-line{stroke:#ff4fad;stroke-width:.35;vector-effect:non-scaling-stroke}.measure-text{fill:#fff;font:1.75px ui-monospace,monospace;paint-order:stroke;stroke:#a52065;stroke-width:.7px}.equal-pill{fill:#ff4fad}.equal-text{fill:#fff;font:bold 1.45px ui-monospace,monospace}</style></defs>${panelFinishSurface(project,w)}${grid}${safe}${view!=='rear'?mountingSvg(project):''}${visible.map(i=>componentSvg(i,catalogMap.get(i.componentId)!,project,selection.has(i.id),view)).join('')}<g id="smart-guide-layer" pointer-events="none"></g>${project.items.length===0?`<g class="empty-panel"><circle cx="${w/2}" cy="${PANEL_H/2-5}" r="5" fill="none" stroke="${project.inkColor}" opacity=".25"/><path d="M${w/2-2} ${PANEL_H/2-5}h4m-2-2v4" stroke="${project.inkColor}" opacity=".4"/><text x="${w/2}" y="${PANEL_H/2+6}" text-anchor="middle" font-size="2.4" fill="${project.inkColor}" opacity=".55">ADD A COMPONENT</text></g>`:''}</svg>`;bindCanvas();renderRuler(w);}
function renderRuler(w:number){const rx=document.querySelector('#ruler-x')!,ry=document.querySelector('#ruler-y')!;rx.innerHTML=Array.from({length:Math.floor(w/10)+1},(_,n)=>`<span style="left:calc(50% - ${w*PX*zoom/2}px + ${n*10*PX*zoom}px)">${n*10}</span>`).join('');ry.innerHTML=Array.from({length:13},(_,n)=>`<span style="top:${74+n*10*PX*zoom}px">${n*10}</span>`).join('');}

function renderSelectionBar(){const el=document.querySelector<HTMLDivElement>('#selection-bar')!,items=selectedItems();if(!items.length){el.classList.remove('show');el.innerHTML='';return;}el.classList.add('show');el.innerHTML=`<span class="selection-count">${items.length===1?catalogMap.get(items[0].componentId)!.name:`${items.length} selected`}</span><span class="bar-divider"></span><button data-selection-action="duplicate">Duplicate</button><button data-selection-action="lock">${items.every(i=>i.locked)?'Unlock':'Lock'}</button><button data-selection-action="hide">Hide</button><button class="danger-text" data-selection-action="delete">Delete</button>`;el.querySelectorAll<HTMLElement>('[data-selection-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.selectionAction;if(action==='duplicate')duplicate();if(action==='delete')remove();if(action==='lock')mutate(()=>items.forEach(i=>i.locked=!items.every(x=>x.locked)));if(action==='hide')mutate(()=>items.forEach(i=>i.hidden=true));});}

function bindCanvas(){const svg=document.querySelector<SVGSVGElement>('#panel-svg')!;svg.querySelectorAll<SVGGElement>('.panel-item').forEach(g=>g.onpointerdown=e=>{e.stopPropagation();const id=g.dataset.id!,item=project.items.find(i=>i.id===id)!;if(e.shiftKey){selection.has(id)?selection.delete(id):selection.add(id);}else if(!selection.has(id)){selection=new Set([id]);}if(!item.locked){const p=point(e,svg);drag={startX:p.x,startY:p.y,orig:new Map(selectedItems().filter(i=>!i.locked).map(i=>[i.id,{x:i.x,y:i.y}])),moved:false};g.setPointerCapture?.(e.pointerId);}render();});svg.onpointerdown=()=>{selection.clear();render();};svg.onpointermove=e=>{const p=point(e,svg);document.querySelector('#coordinates')!.textContent=`X ${p.x.toFixed(1)} · Y ${p.y.toFixed(1)}`;};svg.ondragover=e=>e.preventDefault();svg.ondrop=e=>{e.preventDefault();const id=e.dataTransfer?.getData('component');if(id){const p=point(e,svg);add(id,p.x,p.y);}};}
function point(e:PointerEvent|DragEvent,svg:SVGSVGElement){const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM()!.inverse());}

function smartPosition(item:Item,x:number,y:number){
  const others=project.items.filter(i=>!selection.has(i.id)&&!i.hidden),tolerance=1.4/zoom,w=panelWidth(project.panel);let guide='';
  const snapAxis=(axis:'x'|'y',value:number,size:number,limit:number)=>{const own=[value-size/2,value,value+size/2],targets=[0,limit/2,limit,...others.flatMap(o=>axis==='x'?[o.x-o.width/2,o.x,o.x+o.width/2]:[o.y-o.height/2,o.y,o.y+o.height/2])];let best=Infinity,delta=0,target=0;own.forEach(a=>targets.forEach(t=>{const d=t-a;if(Math.abs(d)<Math.abs(best)){best=d;delta=d;target=t;}}));if(Math.abs(best)<=tolerance){guide+=axis==='x'?`<line class="smart-line" x1="${target}" y1="0" x2="${target}" y2="${PANEL_H}"/>`:`<line class="smart-line" x1="0" y1="${target}" x2="${w}" y2="${target}"/>`;return value+delta;}return value;};
  x=snapAxis('x',x,item.width,w);y=snapAxis('y',y,item.height,PANEL_H);
  let l=x-item.width/2,r=x+item.width/2,t=y-item.height/2,b=y+item.height/2;
  const row=others.filter(o=>Math.min(b,o.y+o.height/2)-Math.max(t,o.y-o.height/2)>-2),left=row.filter(o=>o.x+o.width/2<=l).sort((a,b)=>b.x+b.width/2-(a.x+a.width/2))[0],right=row.filter(o=>o.x-o.width/2>=r).sort((a,b)=>a.x-a.width/2-(b.x-b.width/2))[0];
  if(left&&right){const le=left.x+left.width/2,re=right.x-right.width/2,lg=l-le,rg=re-r;if(Math.abs(lg-rg)<=tolerance*1.6){const dx=(rg-lg)/2;x+=dx;l+=dx;r+=dx;const gap=(l-le);guide+=horizontalMeasure(le,l,y, gap,true)+horizontalMeasure(r,re,y,gap,true);}else{guide+=horizontalMeasure(le,l,y,lg,false)+horizontalMeasure(r,re,y,rg,false);}}
  else if(left){const le=left.x+left.width/2;guide+=horizontalMeasure(le,l,y,l-le,false);}else if(right){const re=right.x-right.width/2;guide+=horizontalMeasure(r,re,y,re-r,false);}
  const col=others.filter(o=>Math.min(r,o.x+o.width/2)-Math.max(l,o.x-o.width/2)>-2),above=col.filter(o=>o.y+o.height/2<=t).sort((a,b)=>b.y+b.height/2-(a.y+a.height/2))[0],below=col.filter(o=>o.y-o.height/2>=b).sort((a,b)=>a.y-a.height/2-(b.y-b.height/2))[0];
  if(above&&below){const ae=above.y+above.height/2,be=below.y-below.height/2,tg=t-ae,bg=be-b;if(Math.abs(tg-bg)<=tolerance*1.6){const dy=(bg-tg)/2;y+=dy;t+=dy;b+=dy;const gap=t-ae;guide+=verticalMeasure(ae,t,x,gap,true)+verticalMeasure(b,be,x,gap,true);}else{guide+=verticalMeasure(ae,t,x,tg,false)+verticalMeasure(b,be,x,bg,false);}}
  else if(above){const ae=above.y+above.height/2;guide+=verticalMeasure(ae,t,x,t-ae,false);}else if(below){const be=below.y-below.height/2;guide+=verticalMeasure(b,be,x,be-b,false);}
  return{x,y,guide};
}
function horizontalMeasure(a:number,b:number,y:number,d:number,equal:boolean){if(d<.2)return'';const mid=(a+b)/2,yy=Math.max(2,Math.min(PANEL_H-2,y));return`<path class="measure-line" d="M${a} ${yy-1.2}v2.4m0-1.2H${b}m0-1.2v2.4"/><text class="measure-text" x="${mid}" y="${yy-1.8}" text-anchor="middle">${d.toFixed(1)} mm</text>${equal?`<rect class="equal-pill" x="${mid-2.2}" y="${yy+.8}" width="4.4" height="2.3" rx="1.1"/><text class="equal-text" x="${mid}" y="${yy+2.45}" text-anchor="middle">=</text>`:''}`;}
function verticalMeasure(a:number,b:number,x:number,d:number,equal:boolean){if(d<.2)return'';const mid=(a+b)/2,xx=Math.max(2,Math.min(panelWidth(project.panel)-2,x));return`<path class="measure-line" d="M${xx-1.2} ${a}h2.4m-1.2 0V${b}m-1.2 0h2.4"/><text class="measure-text" x="${xx+2}" y="${mid+.6}">${d.toFixed(1)} mm</text>${equal?`<rect class="equal-pill" x="${xx-3.4}" y="${mid-1.15}" width="2.3" height="2.3" rx="1.1"/><text class="equal-text" x="${xx-2.25}" y="${mid+.55}" text-anchor="middle">=</text>`:''}`;}

function add(componentId:string,x?:number,y?:number){const d=catalogMap.get(componentId);if(!d)return;const w=panelWidth(project.panel);const item:Item={id:uid(),componentId,x:sv(x??w/2),y:sv(y??PANEL_H/2),rotation:0,label:d.label,color:d.color,width:d.width,height:d.height,value:.62,locked:false,hidden:false,role:d.renderer==='led'?'light':d.renderer==='knob'||d.renderer==='slider'||d.renderer==='button'||d.renderer==='toggle'?'param':d.renderer==='jack'?'input':'none',identifier:''};selection=new Set([item.id]);mutate(()=>project.items.push(item));notify(`${d.name} added`);}

function renderInspector(){const el=document.querySelector<HTMLDivElement>('#inspector')!;let items=selectedItems();if(inspectorTab==='layers'){document.querySelector('#inspector-title')!.textContent='Object layers';el.innerHTML=`<div class="pane-intro"><strong>${project.items.length} objects</strong><span>Select, hide or lock panel objects.</span></div><div id="layers"></div>`;renderLayers();return;}if(inspectorTab==='panel')items=[];document.querySelector('#inspector-title')!.textContent=inspectorTab==='panel'?'Panel settings':items.length>1?`${items.length} selected`:items.length===1?'Component':'Panel overview';if(items.length===0){const warnings=preflight();el.innerHTML=`<div class="section-card"><div class="section-label">Panel geometry</div>${field('Width','hp',project.panel.hp,'number',1,'HP')}<div class="form-row"><label>Width profile</label><select id="width-mode"><option value="doepfer">Doepfer compatible</option><option value="nominal">Nominal HP × 5.08</option><option value="custom">Custom width</option></select></div>${project.panel.widthMode==='custom'?field('Custom width','customWidth',project.panel.customWidth,'number',.01,'mm'):''}<div class="two-col">${field('Thickness','thickness',project.panel.thickness,'number',.1,'mm')}<div class="form-row"><label>Mounting</label><select id="mounting"><option value="none">None</option><option value="two">2 slots</option><option value="four">4 slots</option></select></div></div></div><div class="section-card finish-section"><div class="section-label">Surface finish</div><p class="section-hint">Choose a designed material, then customize its palette below.</p><div class="finish-grid">${finishCards()}</div></div><div class="section-card"><div class="section-label">Custom palette</div><div class="named-colors"><label><span>Panel</span><input id="panel-color" aria-label="Panel colour" type="color" value="${project.panelColor}"></label><label><span>Ink</span><input id="ink-color" aria-label="Ink colour" type="color" value="${project.inkColor}"></label><label><span>Accent</span><input id="accent-color" aria-label="Accent colour" type="color" value="${project.accentColor}"></label></div></div><div class="subhead preflight-head">Preflight <span class="badge ${warnings.length?'warning':'good'}">${warnings.length||'Clear'}</span></div><div class="preflight">${warnings.length?warnings.map(w=>`<button class="issue"><span>▲</span>${w}</button>`).join(''):`<div class="clear-state">✓ No boundary or keepout collisions detected.</div>`}</div>`;bindPanelInspector();return;}
 if(items.length>1){el.innerHTML=`<div class="selection-summary"><span class="selection-kicker">Multi-selection</span><strong>${items.length} components</strong><span>Align centres or create mathematically equal spacing.</span></div><div class="section-card"><div class="section-label">Align & distribute</div><div class="action-grid"><button id="i-align-x">Align X</button><button id="i-align-y">Align Y</button><button id="i-distribute-h" ${items.length<3?'disabled':''}>Equal space H</button><button id="i-distribute-v" ${items.length<3?'disabled':''}>Equal space V</button><button id="i-center">Centre panel</button></div></div><button class="tool-button wide" id="duplicate">Duplicate selection</button>`;bindGroupButtons('i-');document.querySelector('#duplicate')!.addEventListener('click',duplicate);return;}
 const i=items[0],d=catalogMap.get(i.componentId)!;el.innerHTML=`<div class="part-heading"><span class="part-thumbnail large">${partThumbnail(d.renderer,i.color,d.orientation,d.id)}</span><div><strong>${d.name}</strong><small>${d.manufacturer?`${d.manufacturer} · ${d.partNumber}`:d.description}</small><div class="mechanical-line">${d.id.includes('encoder')?'Endless rotation · Push switch · ':d.id.includes('lit')?'Illuminated · ':''}${d.cutout?cutoutText(d): 'No cutout'} · ${d.depth?`${d.depth} mm deep`:'surface'}</div></div><span class="badge">${d.status}</span></div><div class="inspector-section"><div class="section-label">Transform</div><div class="two-col">${field('X','x',i.x,'number',.1,'mm')}${field('Y','y',i.y,'number',.1,'mm')}</div><div class="two-col">${field('Width','width',i.width,'number',.1,'mm')}${field('Height','height',i.height,'number',.1,'mm')}</div>${field('Rotation','rotation',i.rotation,'number',1,'°')}</div><div class="inspector-section"><div class="section-label">Appearance</div>${d.renderer==="image"?imageControl(i):""}${d.renderer!=='led'&&d.renderer!=='hole'?field('Label','label',i.label,'text'):''}${['knob','slider','touch','led'].includes(d.renderer)?field('Preview value','value',i.value,'range',.01):''}<div class="form-row"><label>Component colour</label><div class="color-row"><input id="item-color" aria-label="Component colour" type="color" value="${i.color}"><input id="item-color-text" aria-label="Component colour hex" value="${i.color}"></div></div></div><div class="inspector-section"><div class="section-label">Export mapping</div><div class="form-row"><label>VCV role</label><select id="role">${['none','param','input','output','light','custom'].map(x=>`<option value="${x}" ${i.role===x?'selected':''}>${x}</option>`).join('')}</select></div>${field('Identifier','identifier',i.identifier,'text')}<div class="meta-grid"><span>Cutout</span><strong>${d.cutout?cutoutText(d):'None'}</strong><span>Rear depth</span><strong>${d.depth?`${d.depth} mm`:'—'}</strong><span>Keepout</span><strong>${d.keepout?`${d.keepout} mm`:'—'}</strong></div></div><div class="button-row layer-order"><button class="tool-button wide" id="send-back">Send back</button><button class="tool-button wide" id="bring-forward">Bring forward</button></div><div class="button-row"><button class="tool-button wide" id="duplicate">Duplicate</button><button class="tool-button" id="lock">${i.locked?'Unlock':'Lock'}</button></div>`;bindItemInspector(i);}

function field(label:string,id:string,value:string|number,type:string,step:string|number='',unit=''){return`<div class="form-row"><label>${label}</label><div class="input-unit"><input id="field-${id}" type="${type}" value="${esc(String(value))}" ${step!==''?`step="${step}"`:''} ${type==='range'?'min="0" max="1"':''}>${unit?`<span>${unit}</span>`:''}</div></div>`;}
function bindPanelInspector(){const get=(id:string)=>document.querySelector<HTMLInputElement|HTMLSelectElement>(id)!;get('#field-hp').onchange=e=>mutate(()=>{project.panel.hp=Math.max(2,Math.min(84,Number((e.target as HTMLInputElement).value)));});get('#width-mode').value=project.panel.widthMode;get('#width-mode').onchange=e=>mutate(()=>project.panel.widthMode=(e.target as HTMLSelectElement).value as Project['panel']['widthMode']);document.querySelector<HTMLInputElement>('#field-customWidth')?.addEventListener('change',e=>mutate(()=>project.panel.customWidth=Number((e.target as HTMLInputElement).value)));get('#field-thickness').onchange=e=>mutate(()=>project.panel.thickness=Number((e.target as HTMLInputElement).value));get('#mounting').value=project.panel.mounting;get('#mounting').onchange=e=>mutate(()=>project.panel.mounting=(e.target as HTMLSelectElement).value as Project['panel']['mounting']);document.querySelectorAll<HTMLElement>('[data-finish]').forEach(b=>b.onclick=()=>mutate(()=>applyFinish(project,b.dataset.finish!)));(['panel','ink','accent'] as const).forEach(k=>get(`#${k}-color`).oninput=e=>{project[`${k}Color`]=(e.target as HTMLInputElement).value;if(k==='panel'){project.panel.finish='custom-flat';document.querySelector('.finish-card.selected')?.classList.remove('selected');}persist();renderCanvas();});}
function bindImageObject(i:Item){const input=document.querySelector<HTMLInputElement>("#item-image-file");if(input)input.onchange=()=>{const file=input.files?.[0];if(!file)return;if(file.type!=="image/png"){notify("Choose a PNG image");return;}if(file.size>1_500_000){notify("PNG must be smaller than 1.5 MB");return;}const reader=new FileReader();reader.onload=()=>{if(typeof reader.result!=="string")return;mutate(()=>{i.imageData=reader.result as string;if(!i.label)i.label=file.name.replace(/\.png$/i,"");});notify("PNG artwork added");};reader.onerror=()=>notify("Could not read that PNG");reader.readAsDataURL(file);};document.querySelector("#remove-item-image")?.addEventListener("click",()=>{mutate(()=>delete i.imageData);notify("PNG artwork removed");});}
function bindItemInspector(i:Item){bindImageObject(i);document.querySelector("#send-back")?.addEventListener("click",()=>moveLayer(i,-1));document.querySelector("#bring-forward")?.addEventListener("click",()=>moveLayer(i,1));['x','y','width','height','rotation','label','value','identifier'].forEach(k=>{const e=document.querySelector<HTMLInputElement>(`#field-${k}`);if(!e)return;e.onchange=ev=>mutate(()=>{const v=(ev.target as HTMLInputElement).value;(i as unknown as Record<string,string|number>)[k]=['label','identifier'].includes(k)?v:Number(v);});e.oninput=k==='value'?ev=>{i.value=Number((ev.target as HTMLInputElement).value);renderCanvas();}:null;});const color=document.querySelector<HTMLInputElement>('#item-color')!,hex=document.querySelector<HTMLInputElement>('#item-color-text')!;color.oninput=()=>{i.color=color.value;hex.value=color.value;renderCanvas();};color.onchange=()=>mutate(()=>i.color=color.value);hex.onchange=()=>mutate(()=>i.color=hex.value);document.querySelector<HTMLSelectElement>('#role')!.onchange=e=>mutate(()=>i.role=(e.target as HTMLSelectElement).value as Item['role']);document.querySelector('#duplicate')!.addEventListener('click',duplicate);document.querySelector('#lock')!.addEventListener('click',()=>mutate(()=>i.locked=!i.locked));}
function renderLayers(){const el=document.querySelector('#layers');if(!el)return;el.innerHTML=`<div class="layers">${[...project.items].reverse().map(i=>{const d=catalogMap.get(i.componentId)!;return`<div class="layer ${selection.has(i.id)?'selected':''}"><button class="layer-main" data-layer="${i.id}"><span class="layer-icon">${partIcon(d.renderer)}</span><span class="layer-name">${esc(i.label||d.name)}</span></button><button class="layer-toggle" data-visibility="${i.id}" aria-label="Toggle visibility">${i.hidden?'○':'●'}</button><button class="layer-toggle" data-lock="${i.id}" aria-label="Toggle lock">${i.locked?'◆':'◇'}</button></div>`}).join('')}</div>`;el.querySelectorAll<HTMLElement>('[data-layer]').forEach(b=>b.onclick=e=>{selection=(e.shiftKey?new Set([...selection,b.dataset.layer!]):new Set([b.dataset.layer!]));render();});el.querySelectorAll<HTMLElement>('[data-visibility]').forEach(b=>b.onclick=()=>{const i=project.items.find(x=>x.id===b.dataset.visibility)!;mutate(()=>i.hidden=!i.hidden);});el.querySelectorAll<HTMLElement>('[data-lock]').forEach(b=>b.onclick=()=>{const i=project.items.find(x=>x.id===b.dataset.lock)!;mutate(()=>i.locked=!i.locked);});}

function preflight(){const out:string[]=[],w=panelWidth(project.panel),items=project.items.filter(i=>!i.hidden);items.forEach((i,n)=>{const d=catalogMap.get(i.componentId)!,b=bounds(i,d);if(b.l<3||b.r>w-3||b.t<3||b.b>PANEL_H-3)out.push(`${d.name} is outside the 3 mm safe boundary.`);for(let j=n+1;j<items.length;j++){const o=items[j],od=catalogMap.get(o.componentId)!,ob=bounds(o,od);if(b.l<ob.r&&b.r>ob.l&&b.t<ob.b&&b.b>ob.t)out.push(`${d.name} overlaps ${od.name}.`);}});return [...new Set(out)].slice(0,12);}
function align(axis:'x'|'y'){const a=selectedItems();if(a.length<2)return;const avg=a.reduce((s,i)=>s+i[axis],0)/a.length;mutate(()=>a.forEach(i=>i[axis]=sv(avg)));}
function distribute(axis:'x'|'y'){const a=selectedItems().sort((p,q)=>p[axis]-q[axis]);if(a.length<3)return;const first=a[0],last=a[a.length-1],totalSpan=last[axis]-first[axis]-(axis==='x'?(first.width+last.width)/2:(first.height+last.height)/2),middleSize=a.slice(1,-1).reduce((s,i)=>s+(axis==='x'?i.width:i.height),0),gap=(totalSpan-middleSize)/(a.length-1);mutate(()=>{let edge=first[axis]+(axis==='x'?first.width:first.height)/2;a.slice(1,-1).forEach(i=>{const size=axis==='x'?i.width:i.height;i[axis]=sv(edge+gap+size/2);edge=i[axis]+size/2;});});notify(`Equal ${axis==='x'?'horizontal':'vertical'} spacing · ${gap.toFixed(1)} mm`);}
function center(){const a=selectedItems();if(!a.length)return;const min=Math.min(...a.map(i=>i.x-i.width/2)),max=Math.max(...a.map(i=>i.x+i.width/2)),dx=panelWidth(project.panel)/2-(min+max)/2;mutate(()=>a.forEach(i=>i.x=sv(i.x+dx)));}
function bindGroupButtons(prefix=''){document.querySelector(`#${prefix}align-x`)?.addEventListener('click',()=>align('x'));document.querySelector(`#${prefix}align-y`)?.addEventListener('click',()=>align('y'));document.querySelector(`#${prefix}distribute-h`)?.addEventListener('click',()=>distribute('x'));document.querySelector(`#${prefix}distribute-v`)?.addEventListener('click',()=>distribute('y'));document.querySelector(`#${prefix}center`)?.addEventListener('click',center);}
function moveLayer(item:Item,delta:number){const from=project.items.findIndex(x=>x.id===item.id),to=Math.max(0,Math.min(project.items.length-1,from+delta));if(from===to)return;mutate(()=>{project.items.splice(from,1);project.items.splice(to,0,item);});}
function duplicate(){const copies=selectedItems().map(i=>({...clone(i),id:uid(),x:sv(i.x+3),y:sv(i.y+3)}));if(!copies.length)return;selection=new Set(copies.map(i=>i.id));mutate(()=>project.items.push(...copies));}
function remove(){if(!selection.size)return;mutate(()=>project.items=project.items.filter(i=>!selection.has(i.id)));selection.clear();render();}
function undo(){if(historyIndex===0)return;project=clone(history[--historyIndex]);selection.clear();persist();render();}
function redo(){if(historyIndex===history.length-1)return;project=clone(history[++historyIndex]);selection.clear();persist();render();}

function newProjectDialog(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">Start a new panel</h2><p>Choose a useful layout, then refine every dimension.</p></div><div class="template-grid"><button class="template" data-template="blank"><div class="template-preview"></div><strong>Blank</strong><small>12 HP</small></button><button class="template" data-template="voice"><div class="template-preview voice"></div><strong>Synth voice</strong><small>12 HP</small></button><button class="template" data-template="mixer"><div class="template-preview mixer"></div><strong>Mixer</strong><small>16 HP</small></button><button class="template" data-template="sequencer"><div class="template-preview seq"></div><strong>Sequencer</strong><small>20 HP</small></button></div><div class="modal-actions"><span>Choosing a template replaces the canvas. A recovery snapshot will be kept.</span><button class="tool-button" id="cancel-modal">Cancel</button></div></div></div>`);document.querySelector('#cancel-modal')!.addEventListener('click',()=>document.querySelector('#modal')!.remove());document.querySelectorAll<HTMLElement>('[data-template]').forEach(b=>b.onclick=()=>makeTemplate(b.dataset.template!));}
function makeTemplate(type:string){saveRecovery();const p=emptyProject();if(type==='voice'){p.name='New synth voice';['knob-large','knob-medium','knob-medium','jack-mono','jack-mono','jack-mono','led-3mm'].forEach((id,n)=>p.items.push(makeItem(id,[30,18,42,18,30,42,30][n],[31,61,61,98,98,98,112][n],['PITCH','SHAPE','MOD','V/OCT','FM','OUT',''][n])));}if(type==='mixer'){p.name='Four channel mixer';p.panel.hp=16;for(let n=0;n<4;n++){p.items.push(makeItem('knob-medium',12+n*19,34,'LEVEL'),makeItem('jack-mono',12+n*19,72,'IN'));}p.items.push(makeItem('knob-large',40,98,'MASTER'),makeItem('jack-mono',62,103,'OUT'));}if(type==='sequencer'){p.name='Eight step sequencer';p.panel.hp=20;for(let n=0;n<8;n++){const x=10+(n%4)*25,y=30+Math.floor(n/4)*34;p.items.push(makeItem('knob-small',x,y,`${n+1}`),makeItem('led-3mm',x,y+10,''));}p.items.push(makeItem('button-round',18,105,'RUN'),makeItem('jack-mono',50,105,'CLOCK'),makeItem('jack-mono',78,105,'CV'));}project=p;history=[clone(p)];historyIndex=0;selection.clear();persist();document.querySelector('#modal')!.remove();render();}
function makeItem(id:string,x:number,y:number,label:string){const d=catalogMap.get(id)!;return{id:uid(),componentId:id,x,y,rotation:0,label,color:d.color,width:d.width,height:d.height,value:.6,locked:false,hidden:false,role:d.renderer==='jack'?'input':d.renderer==='led'?'light':'param',identifier:''} as Item;}

function exportDialog(){const warnings=preflight();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal export-modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>Export panel</h2><p>${project.panel.hp} HP · ${panelWidth(project.panel).toFixed(2)} × ${PANEL_H} mm · ${project.panel.material} ${project.panel.thickness} mm</p></div><div class="export-preflight ${warnings.length?'warning':'good'}"><strong>${warnings.length?`▲ ${warnings.length} preflight issue${warnings.length===1?'':'s'}`:'✓ No layout conflicts detected'}</strong><span>${warnings.length?'Review boundaries and overlaps before fabrication.':'No basic layout conflicts detected. Verify every cutout against the hardware datasheet.'}</span></div><div class="export-options"><button data-export="art"><span>◈</span><div><strong>Artwork SVG</strong><small>Panel graphics at physical size</small></div></button><button data-export="cut"><span>◎</span><div><strong>Cutout SVG</strong><small>Drill and machining geometry only</small></div></button><button data-export="vcv"><span>⌁</span><div><strong>VCV Rack SVG</strong><small>Artwork + coloured helper placeholders</small></div></button><button data-export="bom"><span>≡</span><div><strong>BOM CSV</strong><small>Parts, cutouts, depths and quantities</small></div></button></div><div class="modal-actions"><button class="tool-button" id="cancel-modal">Cancel</button></div></div></div>`);document.querySelector('#cancel-modal')!.addEventListener('click',()=>document.querySelector('#modal')!.remove());document.querySelectorAll<HTMLElement>('[data-export]').forEach(b=>b.onclick=()=>{doExport(b.dataset.export!);document.querySelector('#modal')!.remove();});}
function helpDialog(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal shortcuts-modal" role="dialog" aria-modal="true" aria-labelledby="shortcuts-title"><div class="modal-head"><span class="eyebrow">Five08 guide</span><h2 id="shortcuts-title">Work quickly and precisely</h2><p>Drag parts onto the panel, or click a library row to add at centre.</p></div><div class="shortcut-grid"><section><h3>Selection</h3><div><span>Select all</span><kbd>⌘ A</kbd></div><div><span>Add to selection</span><kbd>⇧ Click</kbd></div><div><span>Duplicate</span><kbd>⌘ D</kbd></div><div><span>Delete</span><kbd>⌫</kbd></div></section><section><h3>Precision</h3><div><span>Nudge 0.1 mm</span><kbd>Arrow</kbd></div><div><span>Nudge 1 mm</span><kbd>⇧ Arrow</kbd></div><div><span>Undo</span><kbd>⌘ Z</kbd></div><div><span>Find a part</span><kbd>/</kbd></div></section></div><div class="guide-tip"><strong>Smart positioning</strong><span>Blue guides align centres and edges. Pink measurements show neighbour gaps; matching “=” badges mean the gaps are equal. Select three or more parts to apply exact horizontal or vertical distribution.</span></div><div class="modal-actions"><button class="tool-button primary" id="cancel-modal">Got it</button></div></div></div>`);document.querySelector('#cancel-modal')!.addEventListener('click',closeModal);document.querySelector<HTMLElement>('#cancel-modal')!.focus();}
function closeModal(){document.querySelector('#modal')?.remove();}
function doExport(type:string){if(type==='cut'){download(`${slug(project.name)}-cut.svg`,cutoutSvg(project,catalogMap),'image/svg+xml');notify('Cutout SVG exported');return;}if(type==='bom'){const counts=new Map<string,number>();project.items.forEach(i=>counts.set(i.componentId,(counts.get(i.componentId)||0)+1));const rows=['Quantity,Part,Manufacturer,Part number,Cutout mm,Rear depth mm',...[...counts].map(([id,n])=>{const d=catalogMap.get(id)!;return`${n},"${d.name}","${d.manufacturer||''}","${d.partNumber||''}",${d.cutout||''},${d.depth||''}`;})];download(`${slug(project.name)}-bom.csv`,rows.join('\n'),'text/csv');notify('BOM exported');return;}const old=view;view=type==='cut'?'cutout':'design';renderCanvas();const svg=document.querySelector<SVGSVGElement>('#panel-svg')!.cloneNode(true) as SVGSVGElement;svg.querySelectorAll('.design-guide,.selection-ui,.empty-panel').forEach(n=>n.remove());svg.removeAttribute('style');svg.setAttribute('width',`${panelWidth(project.panel).toFixed(2)}mm`);svg.setAttribute('height',`${PANEL_H}mm`);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');if(type==='vcv'){const colors={param:'#ff0000',input:'#00ff00',output:'#0000ff',light:'#ff00ff',custom:'#ffff00'};const layer=document.createElementNS('http://www.w3.org/2000/svg','g');layer.setAttribute('id','components');project.items.filter(i=>i.role!=='none').forEach(i=>{const e=document.createElementNS('http://www.w3.org/2000/svg','circle');e.setAttribute('cx',String(i.x));e.setAttribute('cy',String(i.y));e.setAttribute('r','1.5');e.setAttribute('fill',colors[i.role as keyof typeof colors]||'#ffff00');if(i.identifier)e.setAttribute('id',i.identifier);layer.appendChild(e);});svg.appendChild(layer);}download(`${slug(project.name)}-${type}.svg`,new XMLSerializer().serializeToString(svg),'image/svg+xml');view=old;renderCanvas();notify('SVG exported');}
function download(name:string,data:string,type:string){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}
function slug(s:string){return s.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'panel';}

document.querySelector<HTMLInputElement>('#library-search')!.oninput=e=>{libraryQuery=(e.target as HTMLInputElement).value;renderLibrary();};document.querySelector('#delete')!.addEventListener('click',remove);document.querySelector('#undo')!.addEventListener('click',undo);document.querySelector('#redo')!.addEventListener('click',redo);document.querySelector('#new-project')!.addEventListener('click',newProjectDialog);document.querySelector('#export')!.addEventListener('click',exportDialog);document.querySelector('#help')!.addEventListener('click',helpDialog);document.querySelector('#save-json')!.addEventListener('click',()=>download(`${slug(project.name)}.panel.json`,JSON.stringify(project,null,2),'application/json'));document.querySelector('#open-json')!.addEventListener('click',()=>document.querySelector<HTMLInputElement>('#file-input')!.click());document.querySelector<HTMLInputElement>('#file-input')!.onchange=async e=>{const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(f.size>5_000_000){notify("Project file is larger than 5 MB");return;}try{saveRecovery();project=parseProject(JSON.parse(await f.text()),catalogMap);history=[clone(project)];historyIndex=0;selection.clear();persist();render();notify('Project opened');}catch(err){notify(err instanceof Error?err.message:'Invalid project');}};document.querySelector<HTMLInputElement>('#project-name')!.onchange=e=>mutate(()=>project.name=(e.target as HTMLInputElement).value);document.querySelectorAll<HTMLElement>('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view as typeof view;render();});document.querySelectorAll<HTMLElement>('[data-inspector-tab]').forEach(b=>b.onclick=()=>{inspectorTab=b.dataset.inspectorTab as typeof inspectorTab;render();});document.querySelector('#collapse-left')!.addEventListener('click',()=>{leftOpen=false;renderChrome();});document.querySelector('#open-left')!.addEventListener('click',()=>{leftOpen=true;renderChrome();});document.querySelector('#collapse-right')!.addEventListener('click',()=>{rightOpen=false;renderChrome();});document.querySelector('#open-right')!.addEventListener('click',()=>{rightOpen=true;renderChrome();});document.querySelector('#warning-count')!.addEventListener('click',()=>{rightOpen=true;inspectorTab='panel';render();});bindGroupButtons();document.querySelector('#smart-guides')!.addEventListener('click',()=>{smartGuides=!smartGuides;renderChrome();});document.querySelector('#toggle-safe')!.addEventListener('click',()=>{showSafe=!showSafe;render();});document.querySelector('#zoom-in')!.addEventListener('click',()=>{zoom=Math.min(2,zoom+.1);render();});document.querySelector('#zoom-out')!.addEventListener('click',()=>{zoom=Math.max(.35,zoom-.1);render();});document.querySelector('#zoom-fit')!.addEventListener('click',()=>{zoom=Math.min(1.25,(window.innerHeight-190)/(PANEL_H*PX));render();});document.querySelector('#zoom-100')!.addEventListener('click',()=>{zoom=1;render();});document.querySelector('#snap-toggle')!.addEventListener('click',()=>{snap=!snap;render();});document.querySelector('#grid-cycle')!.addEventListener('click',()=>{gridIndex=(gridIndex+1)%grids.length;document.querySelector('#grid-cycle')!.textContent=`${grids[gridIndex]} mm`;render();});document.querySelector('#grid-toggle')!.addEventListener('click',()=>{showGrid=!showGrid;render();});
window.addEventListener('pointermove',e=>{if(!drag)return;const svg=document.querySelector<SVGSVGElement>('#panel-svg');if(!svg)return;const p=point(e,svg),dx=p.x-drag.startX,dy=p.y-drag.startY,moving=selectedItems().filter(i=>!i.locked);drag.moved=drag.moved||Math.abs(dx)>.05||Math.abs(dy)>.05;let guide='';moving.forEach((i,n)=>{const o=drag!.orig.get(i.id);if(!o)return;let x=sv(o.x+dx),y=sv(o.y+dy);if(smartGuides&&moving.length===1){const smart=smartPosition(i,x,y);x=smart.x;y=smart.y;guide=smart.guide;}i.x=x;i.y=y;const g=svg.querySelector<SVGGElement>(`[data-id="${i.id}"]`);g?.setAttribute('transform',`translate(${i.x} ${i.y}) rotate(${i.rotation})`);if(n===0)document.querySelector('#coordinates')!.textContent=`X ${i.x.toFixed(1)} · Y ${i.y.toFixed(1)}`;});const layer=svg.querySelector('#smart-guide-layer');if(layer)layer.innerHTML=guide;});window.addEventListener('pointerup',()=>{if(!drag)return;const moved=drag.moved;drag=null;moved?mutate(()=>{}):render();});window.addEventListener('pointercancel',()=>{drag=null;render();});window.addEventListener('keydown',e=>{const t=e.target as HTMLElement;if(e.key==='Escape'&&document.querySelector('#modal')){closeModal();return;}if(['INPUT','SELECT','TEXTAREA'].includes(t.tagName))return;if(e.key==='/'){e.preventDefault();document.querySelector<HTMLInputElement>('#library-search')!.focus();}else if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}else if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='d'){e.preventDefault();duplicate();}else if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='a'){e.preventDefault();selection=new Set(project.items.filter(i=>!i.hidden).map(i=>i.id));render();}else if(['Delete','Backspace'].includes(e.key)){e.preventDefault();remove();}else if(e.key==='?')helpDialog();else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)&&selection.size){e.preventDefault();const d=e.shiftKey?1:.1;mutate(()=>selectedItems().filter(i=>!i.locked).forEach(i=>{if(e.key==='ArrowLeft')i.x-=d;if(e.key==='ArrowRight')i.x+=d;if(e.key==='ArrowUp')i.y-=d;if(e.key==='ArrowDown')i.y+=d;}));}});

render();
